tCursor(crossCursor);	WatchCursor = GetCursor(watchCursor);	MoveCursor = GetCursor(moveCursor);	DeleteCursor = GetCursor(deleteCursor);	OkCursor = GetCursor(okCursor);	CPCursor = GetCursor(cpCursor);	LineCursor = GetCursor(lineCursor);	FrameCursor = GetCursor(frameCursor);	ArrowCursor = GetCursor(arrowCursor);				/* V3.1 */	MoveVerticalCursor = GetCursor(moveVerticalCursor);	// V402	TextCursor = GetCursor(textCursor);					// V403	GetPort(&savePort);	OpenPort(&_screenPort);	screenPort = &_screenPort;	ClipRect(&ScreenBounds);	SetPort(savePort);	deskBounds = ScreenBounds;	deskBounds.top += MenuBarHeight;	InsetRect(&deskBounds, thinMargin, thinMargin);}Boolean HLockIfNecessary(Handle handle)	// V401{	// return TRUE if handle is already locked, else lock it and return FALSE		assert(handle);		MoveHHi(handle);	OSErr moveErr = MemError();	Boolean bAlreadyLocked = memLockedErr == moveErr;	if(!bAlreadyLocked)	{		assert(moveErr == noErr);		HLock(handle);		OSErr lockErr = MemError();		assert(lockErr == noErr);	}		return bAlreadyLocked;}void HUnlockIfNecessary(Handle handle, Boolean bAlreadyLocked)	// V401{	// handle should be locked on entry, unlock it if necessary		assert(handle);		MoveHHi(handle);	OSErr moveErr = MemError();	assert(memLockedErr == moveErr);		if(!bAlreadyLocked)	{		HUnlock(handle);		OSErr unlockErr = MemError();		assert(unlockErr == noErr);	}}Rect *FindBox(Rect *boxes, int nBoxes, Point *point){	int i;	for (i = 0; i < nBoxes; ++i)		if (PtInRect(*point, &boxes[i]))							return &boxes[i];						/* MPW3 - changed pt parameter - 01/02/90 */	return 0;}/* * The Control Manager has no routine that simply redraws a single * control.  If the value and range of a scroll bar change, the * 'official' way to do it is to call SetCtlMin(), SetCtlValue(), and * SetCtlMax().  This causes the control to be redrawn up to 3 times * in succession.  Hence this routine. */void SetControl(ControlHandle control, int cMin, int cMax, int cValue,					int redraw){	register ControlPtr c = *control;	int changed;	changed = cMin != c->contrlMin 			  || cMax != c->contrlMax			  || cValue != c->contrlValue;	c->contrlMin = cMin;	c->contrlMax = cMax;	c->contrlValue = cValue;	if (redraw && changed) {		/* trick the control manager into redrawing the control */		c->contrlVis = FALSE;		ShowControl(control);	}}/* * Wait n ticks for vertical retrace. */void WaitForRetrace(int n){	long ticks = TickCount() + n;	while (ticks != TickCount())		continue;}/* * Copy a string of bytes from one place to another. */void copybytes(Ptr src, Ptr dest, int nbytes){	while (nbytes-- > 0)		*dest++ = *src++;}